    id: number;
    documento_tipo: string;
    titular: string;
    label: string;
    obrigatorio?: boolean;
    ativa: boolean;
    documento_id?: number | null;
    esteira_id?: number;
    cedente_id?: string | null;
    extrato_id?: string | null;
}

export async function getEsteiraExigenciasCondicionais(
    esteiraId: number,
): Promise<EsteiraExigenciaCondicional[]> {
    const res = await directApi.get<{ exigencias_condicionais?: EsteiraExigenciaCondicional[] }>(
        `/api/esteiras/${esteiraId}/`,
    );
    return Array.isArray(res.data?.exigencias_condicionais)
        ? res.data.exigencias_condicionais
        : [];
}

