const [outroDocTituloDraft, setOutroDocTituloDraft] = useState('');
const [leadDocsSeed, setLeadDocsSeed] = useState<Dashboard2DocsCedenteRow[]>([]);
const inputRef = useRef<HTMLInputElement | null>(null);
const slotRef = useRef<string | null>(null);

const slots = useMemo(() => (isPj ? SLOTS_PJ_MAIN : SLOTS_REP), [isPj]);

useEffect(() => {
    let cancelled = false;
    if (!leadId) {
        setLeadDocsSeed([]);
        return () => {
            cancelled = true;
        };
    }

    void (async () => {
        try {
            const lead = await getLeadById(leadId);
            const rawDocs = lead?.documentacao_cedente_crm?.docs;
            if (!cancelled && Array.isArray(rawDocs)) {
                setLeadDocsSeed(rawDocs as Dashboard2DocsCedenteRow[]);
            } else if (!cancelled) {
                setLeadDocsSeed([]);
            }
        } catch {
            if (!cancelled) setLeadDocsSeed([]);
        }
    })();

    return () => {
        cancelled = true;
    };
}, [leadId]);

const refetch = useCallback(async () => {
    setLoading(true);
    try {
        const rows = await getDocsFromEsteira(esteiraId);
        const merged = dashboard2MergeEsteiraApiDocsIntoDocsCedente(
            rows as Dashboard2EsteiraDocRow[],
            isPj,
            leadDocsSeed,
        );
        setDocs(merged);
        onDocsChange?.();
    } catch {
        supportError(leadId);
    } finally {
        setLoading(false);
    }
}, [esteiraId, isPj, leadDocsSeed, leadId, onDocsChange]);

useEffect(() => {
    void refetch();
}, [refetch]);

const extras = docs.filter(
    (d) => d.tipoId == null || !slots.some((slot) => slot.id === d.tipoId),
);

async function handleUpload(file: File, slotId: string | null) {
    const fd = new FormData();
    fd.append('arquivo', file);
    const nome = slotId ? file.name : outroDocTituloDraft.trim() || file.name;
    fd.append('nome', nome);
    fd.append('tipo', slotId ? dashboard2ResolveDocumentoTipoForSlot(slotId) : 'OUTROS');
    fd.append('data_documento', new Date().toISOString().slice(0, 10));
    fd.append('status', 'PENDENTE');

    try {
        await uploadDocumentToEsteira(esteiraId, fd);
        sendToastMessage({ type: 'success', title: 'Documento enviado.' });
        setOutroDocTituloDraft('');
        await refetch();
    } catch {
        supportError(leadId);
    }
}

